{"files": {"src/detect.py": "def mode(rule, spec, payload):
    try:
        code = None
        if isinstance(payload, dict):
            for k in ("code", "Code", "CODE"):
                if k in payload:
                    code = payload[k]
                    break
        else:
            code = payload
        at = None
        if isinstance(rule, dict):
            for k in ("at", "At", "AT", "threshold", "Threshold"):
                if k in rule:
                    at = rule[k]
                    break
        if at is None and isinstance(spec, dict):
            r = spec.get("rule", spec.get("Rule"))
            if isinstance(r, dict):
                for k in ("at", "At", "AT", "threshold", "Threshold"):
                    if k in r:
                        at = r[k]
                        break
        if at is None:
            at = 100
        if code is None:
            return "a"
        return "b" if code >= at else "a"
    except Exception:
        return "a"
